  directions: 10,
  lenses: 10,
  scenarios: 20,
  citations: 8,
  predictions: 10,
  params: 10,
  shifts: 20,
  label: 80,
  description: 500,
  paramValue: 200,
  rationale: 1000,
  scenarioTitle: 120,
  scenarioDescription: 1000,
  maxWeight: 100,
